function clean(v) {
  return v == null ? '' : String(v).trim();
}

function parseJsonLine(value) {
  try {
    return JSON.parse(value);
  } catch (_) {
    return null;
  }
}

const prior =
  $('Mark Compression Target — Start').isExecuted
    ? $('Mark Compression Target — Start').last().json
    : $('Mark Compression Target — Resume').last().json;

const rawStdout = clean($json.stdout);
const rawStderr = clean($json.stderr);

// Compress Session deliberately prints explicit markers so we can never lose
// Python's stdout/stderr behind a shell-level exit code.
let pythonStdout = rawStdout;
let pythonStderr = rawStderr;
let pythonExit = Number($json.exitCode ?? $json.code ?? 0);

const exitMatch = rawStdout.match(/__HERMES_EXIT__=(\d+)/);
if (exitMatch) {
  pythonExit = Number(exitMatch[1]);
}

const stdoutMarker = '__HERMES_STDOUT__';
const stderrMarker = '__HERMES_STDERR__';

const stdoutPos = rawStdout.indexOf(stdoutMarker);
const stderrPos = rawStdout.indexOf(stderrMarker);

if (stdoutPos >= 0) {
  const afterStdout = rawStdout.slice(stdoutPos + stdoutMarker.length);
  if (stderrPos >= 0 && stderrPos > stdoutPos) {
    pythonStdout = afterStdout.slice(0, stderrPos - (stdoutPos + stdoutMarker.length)).trim();
    pythonStderr = afterStdout.slice(stderrPos - (stdoutPos + stdoutMarker.length) + stderrMarker.length).trim();
  } else {
    pythonStdout = afterStdout.trim();
  }
}

let response = {};
if (pythonStdout) {
  const lines = pythonStdout
    .split(/\r?\n/)
    .map(x => x.trim())
    .filter(Boolean);

  for (let i = lines.length - 1; i >= 0; i--) {
    const parsed = parseJsonLine(lines[i]);
    if (parsed && typeof parsed === 'object') {
      response = parsed;
      break;
    }
  }
}

if (!Object.keys(response).length && pythonStderr) {
  const lines = pythonStderr
    .split(/\r?\n/)
    .map(x => x.trim())
    .filter(Boolean);

  for (let i = lines.length - 1; i >= 0; i--) {
    const parsed = parseJsonLine(lines[i]);
    if (parsed && typeof parsed === 'object') {
      response = parsed;
      break;
    }
  }
}

const responseError = clean(
  response.error ??
  response.message ??
  response.details?.error
);

const diagnostic =
  responseError ||
  pythonStderr ||
  (pythonStdout && !Object.keys(response).length ? pythonStdout : '') ||
  (pythonExit !== 0 ? `Compression process exited with code ${pythonExit}.` : '') ||
  `Compression process returned no JSON. Raw n8n output: ${JSON.stringify($json)}`;

