  response.compression_status ??
  response.status
).toLowerCase();

const commitStatus = clean(
  response.commit_status
).toLowerCase();

const failed =
  Boolean(response.compression_failed) ||
  pythonExit !== 0 ||
  ['failed', 'aborted', 'cancelled', 'canceled'].includes(status) ||
  ['failed', 'aborted'].includes(commitStatus);

const completed =
  !failed &&
  (
    Boolean(response.compression_completed) ||
    status === 'completed' ||
    commitStatus === 'committed'
  );

const targetedSession = clean(
  prior.compression_target_session_id ??
  prior.session_id ??
  prior.requested_session_id
);

const sessionId = targetedSession || clean(
  response.compression_session_id ??
  response.session_id ??
  response.requested_session_id
);

