  json: {
    ...prior,
    compression_run_id: '',
    compression_session_id: sessionId,
    compression_target_session_id: sessionId,
    compression_status: failed ? 'failed' : (completed ? 'completed' : status),
    compression_error: diagnostic,
    compression_output: clean(response.compression_output ?? response.output ?? pythonStdout),
    compression_stdout: pythonStdout,
    compression_stderr: pythonStderr,
    compression_exit_code: pythonExit,
    compression_response: response,
    compression_failed: failed,
    compression_completed: completed,
    session_id: sessionId,
    requested_session_id: sessionId,
    run_id: '',
  },
